WFJ.Data.add("gossip", {
  ["44036df1ca84a2fc"] = { "Sembra che tu abbia la stoffa di <un/una> grande fabbro. Ma prima di insegnarti qualcosa devo sapere se hai quel che serve.", "." },
  ["44048bd35cdc6e20"] = { "Le ⟦Burning Steppes=Steppe Ardenti⟧ sono un luogo pericoloso, ma gli studiosi come me farebbero quasi di tutto per far progredire la conoscenza.", "." },
  ["4405cbd334f781a8"] = { "Sono assolutamente <sicuro/sicura> di voler imparare la Conciatura Elementale.", "." },
  ["4406e2739da5bb53"] = { "La tua attuale abilità supera le mie capacità didattiche. Dovresti rivolgerti alla mia collega, la gnoma Trixie Quickswitch, a ⟦Ironforge=Forgiardente⟧!", "." },
  ["44076998acebb96a"] = { "Pele'keiki lo sa, sembra impossibile pure a lui, ma noi avere tutto il fiordifuoco che l'⟦Horde=Orda⟧ vuole per la guerra. Se tu non sentirti troppo pigr<o/a>, Pele'keiki pensa che tu aiutare gli altri qui. Di sicuro avere tante cose che vogliono che tu prendi per loro.", "." },
  ["4407d5027fc425c8"] = { "Maledizione... Devono essere stati i goblin... Vediamo quanto è grave il danno.", "." },
  ["440f87ffcf059ed8"] = { "Gli insegnerei a forgiare demoni in cambio della sua anima. L'anima di un orco ⟦Blackrock=Roccianera⟧ vale ben poco, ma in tempi così difficili un'anima, qualunque anima, è meglio di niente.", "." },
  ["4415916d3f7993f0"] = { "Solo un bastone? Vuoi che ti mostri cosa sa fare «solo un bastone»?", "." },
  ["4415e7de5975d1bb"] = { "I Piccatonante hanno scoperto antichi manufatti nella ⟦Alterac Valley=Valle d'Alterac⟧, ma gli orchi Lupi Bianchi non vedono di buon occhio gli esploratori. Se i nani devono combattere per conoscere i loro antenati, che così sia!\n\nPer vincere questa battaglia, sconfiggi l'orco ⟦Drek'Thar=Drek'thar⟧ nella ⟦Frostwolf Keep=Rocca dei Lupi Bianchi⟧. Che la fortuna sia con te, {class}!", "." },
  ["441c93721898ff2e"] = { "Dunque tu saresti ⟦Klinfran the Crazed=Klinfran il Pazzo⟧? Peccato, mi aspettavo una vera sfida. Osi affrontarmi nella tua vera forma?", "." },
  ["441e7a4e3c31a238"] = { "Via, a ⟦Undercity=Sepulcra⟧, {name}!", "." },
  ["442340e55e740083"] = { "Signore Hir'eek, concedimi le ali della vendetta!", "." },
  ["44237eb400651463"] = { "Una risposta interessante alla mia domanda... e sbagliata.", "." },
  ["44246aed8dd5264f"] = { "Ottimo lavoro, soldato. Puoi andare!", "." },
  ["4424a8cacd07199e"] = { "Yiieeeee! Io corre!", "." },
  ["44348ed622893f20"] = { "ASSAPORO IL SANGUE DELLA VITA!", "." },
  ["4436eeb65bb4915d"] = { "Gnomeregan si trova nel Dun Morogh occidentale.", "." },
  ["443d9598ae60cdd0"] = { "<Bugiardo/Bugiarda>!", "." },
  ["44403091060725d5"] = { "Questa città riarsa dal sole è la dimora dei troll Sabbiafurente, noti per la loro particolare spietatezza e per il loro oscuro misticismo. Le leggende dei troll parlano di una potente spada chiamata Sul'thraze the Lasher, un'arma capace di instillare paura e debolezza anche nei nemici più temibili. Molto tempo fa l'arma fu spezzata in due. Tuttavia, si dice che le due metà si trovino da qualche parte entro le mura di Zul'farrak.", "." },
  ["4443a3964caa4561"] = { "Quando l'⟦Horde=Orda⟧ fu annientata, gli uomini tornarono qui e cominciarono a ricostruire la città un tempo grandiosa, come testimonianza della nostra sopravvivenza.", "." },
  ["44590de059282562"] = { "Hai imparato molto, ma sento che gli spiriti hanno ancora altro da insegnarti. Posso mettere il tuo piede sul sentiero, ma non guidare i tuoi passi. Va' a cercare ⟦Saru Steelfury=Saru Furiaferro⟧ a Orgrimmar: lì comincia il prossimo tratto del tuo viaggio.", "." },
  ["44612d35b34a2a0b"] = { "Cercavo un po' di aiuto. Visto che hai l'abilità, immagino che andrai bene, purché tu abbia anche fegato.", "." },
  ["4464b878878576d3"] = { "Attenzione a entrare nel territorio dei Lupi Bianchi, soldato. Quel maledetto posto è pieno di trappole! Mine a non finire! Parla con il nostro esperto di esplosivi nella prima torre in prima linea per saperne di più. Di sicuro potrebbe insegnarti come disinnescare la situazione.", "." },
  ["44725f3947b3c671"] = { "%s comincia a evocare un ⟦Blackhand Dreadweaver=Mistico del Terrore Manonera⟧!", "." },
  ["4480e881321f09bf"] = { "Ci è voluta la forza di sei combattenti esperti per abbattere una di queste creature, e nonostante ciò è riuscita a stenderne quattro prima che potessimo finirla.\n\nSe queste bestie mostruose comparissero in numero maggiore, i danni che i verrospini potrebbero infliggere a questa terra sarebbero catastrofici.", "." },
  ["4481dfb1d4c9df02"] = { "Tornerò appena avrò sistemato questo pasticcio.", "." },
  ["4486716290068cd7"] = { "Salute, {class}. Il mio titolo è Custode della Fiamma. Durante il Midsummer Fire Festival è mio dovere tenere acceso e vivo questo fuoco accanto a me. Essere scelti per un simile compito è un onore, e lo svolgo con gioia.\n\nCome posso aiutarti?", "." },
  ["4486f2d1bb78998b"] = { "Non è facile proteggere il taglio del legname dell'Orda qui a ⟦Ashenvale=Valtetra⟧, ma non ci siamo mai tirati indietro davanti alla battaglia! Gli elfi della notte e i loro alleati cadranno!", "." },
  ["448df2265939a6f2"] = { "%s prende di nuovo la mira sulle bottiglie...", "." },
  ["449214de19f3e3e1"] = { "L'anziano Obsidian si aggira vicino alla ⟦Sepulcher=Mausolea⟧, nella ⟦Silverpine Forest=Selva Pinargento⟧.", "." },
  ["44947817c3a2554b"] = { "La capitana Ballinda Stonehearth arriverà presto alla sua guarnigione. Presto si combatterà una nuova battaglia!", "." },
  ["44968155d01c9739"] = { "Incredibile. Le tue pozioni rivelano una conoscenza che rivaleggia con la mia. Non posso addestrarti oltre, ma parla con l'orco Rogvar di ⟦Stonard=Pietrachiusa⟧, nella ⟦Swamp of Sorrows=Palude del Dolore⟧. È noto per i suoi esperimenti all'avanguardia.", "." },
  ["44a25594d97e4f11"] = { "La tua istruzione procede bene. Dovresti trarre orgoglio dai tuoi risultati.", "." },
  ["44aa25a6d19877f2"] = { "Bella forma, {name}. Scommetto un boccale pieno al Bruuk's Corner che anche la funzione è altrettanto solida. Sai, potresti parlare con ⟦Myolor Sunderfury=Mastro Mondo Fendifuria⟧. Ti metterà in riga.", "." },
  ["44c3db9dc48cd03e"] = { "Da dove vengo io, se apri la cella di un altro detenuto ti accoltellano!", "." },
  ["44c41fdd6707ef74"] = { "Credi davvero di cavartela bene? Ah! Il nostro numero è illimitato!", "." },
  ["44c8d7c159f24c5e"] = { "Dopo tutto quello che abbiamo passato? Be', tanto non mi stavi simpatic<o/a>!!", "." },
  ["44d10beb566ee504"] = { "Shoja'my è davanti alla locanda. Ora circola, ho da fare.", "." },
  ["44dd592db0a2c898"] = { "Sarai una facile preda, {class}.", "." },
  ["44e1a1f0aebff2f3"] = { "Sono Zanza, un Loa di Zandalar. Da Zandalar ho assunto questa forma eterea per aiutare il mio popolo. Hakkar non ha alcun dominio sulla mia anima.\n\nAiuto chi ha aiutato il popolo degli Zandalari.", "." },
  ["44e750ffe06de021"] = { "%s proietta la sua immensa ombra su tutta ⟦Silithus=Silitus⟧.", "." },
  ["44e85beb778d8492"] = { "La corruzione ha portato alla follia {name}!", "." },
  ["44eecdac834fd9e4"] = { "Che il vostro spirito si sollevi! Stringetevi attorno al vostro campione, crogiolatevi nella sua gloria! Esultate al grido di battaglia di chi ha ucciso il drago!", "." },
  ["44efd9c9e9bf8a2e"] = { "Mi hai portato davvero la pelle della bestia? Be'... Lascia che ti mostri...", "." },
  ["44f65eec239227be"] = { "Grazie! Grazie, <sacerdote/sacerdotessa>. Ora posso affrontare quegli umani con il tuo potere alle spalle!", "." },
  ["44fa6d863b1e9dea"] = { "La legione Manonera indosserà la tua pelle come accessorio di moda!", "." },
})
